"""The story graph: generated by models, validated and traversed by code.

Nodes are the plan, script units, and scenes. Edges are the transitions between
adjacent units and adjacent scenes (derived from their order, with each scene's
morph bridge), unit-to-arc-phase and unit-to-claim links, and scene-to-unit links.
Structural checks here are exact and block progress; the judgement tasks turn every
node and edge into one focused System 1 question batch, which `graph.py` fans out in
parallel.
"""

import difflib
import re
from collections.abc import Collection, Sequence
from typing import Any, Literal, NamedTuple

from content.judging.judge import JudgementTask
from content.judging.questions import QUESTIONS, Target
from content.schemas.audience import AudienceFlag, AudienceReport, StoryDecisions
from content.schemas.fact_check import FactCheckReport
from content.schemas.judgement import Judgement
from content.schemas.plan import EditorialBrief
from content.schemas.research import ResearchPack
from content.schemas.script import ScriptPackage, ScriptUnit
from content.schemas.visuals import Scene, VisualPackage


def opening_issues(
    script: ScriptPackage, brief: EditorialBrief, research: ResearchPack
) -> list[str]:
    """The first seconds decide whether anyone stays: a hook built on verified fact, then
    who and what this is about. How long each takes is the writer's call, judged by Jev."""
    units = script.script_units
    hook = units[0]
    issues = []
    verified = {claim.claim_id for claim in research.verified_facts}
    if not hook.claim_ids or any(claim not in verified for claim in hook.claim_ids):
        issues.append(
            f"{hook.unit_id}: the hook must rest only on verified claims; open on the most "
            "arresting verified fact."
        )
    if brief.hook_claim_id and brief.hook_claim_id not in hook.claim_ids:
        issues.append(f"{hook.unit_id}: the plan's hook is {brief.hook_claim_id}; open with it.")
    if len(units) > 1 and units[1].narrative_function != "orient":
        issues.append(
            f"{units[1].unit_id}: right after the hook, orient the viewer: who and what this "
            "is about, and why it matters. Mark it `orient`."
        )
    return issues


def script_issues(
    script: ScriptPackage,
    brief: EditorialBrief,
    research: ResearchPack,
) -> list[str]:
    issues: list[str] = []
    known_claim_ids = {claim.claim_id for claim in research.all_claims}
    used_claim_ids = set(script.claims_used)
    if unknown := used_claim_ids - known_claim_ids:
        issues.append(f"Script cites unknown research claims: {', '.join(sorted(unknown))}.")
    if missing := set(brief.required_claim_ids) - used_claim_ids:
        issues.append(f"Script omits required research claims: {', '.join(sorted(missing))}.")
    if excluded := set(brief.excluded_claim_ids) & used_claim_ids:
        issues.append(f"Script uses excluded research claims: {', '.join(sorted(excluded))}.")
    phase_ids = {phase.phase_id for phase in brief.arc}
    unplanned = [unit.unit_id for unit in script.script_units if unit.arc_phase_id not in phase_ids]
    if unplanned:
        issues.append(
            f"Units not linked to a creative-plan phase: {', '.join(unplanned)}. "
            f"Use one of: {', '.join(sorted(phase_ids))}."
        )
    return issues


def fact_check_issues(
    report: FactCheckReport,
    script: ScriptPackage,
    research: ResearchPack,
) -> list[str]:
    """Every spoken unit must be audited or explicitly declared non-factual."""
    issues: list[str] = []
    unit_ids = {unit.unit_id for unit in script.script_units}
    audited = {unit_id for finding in report.claim_findings for unit_id in finding.script_unit_ids}
    declared = set(report.non_factual_unit_ids)
    if unknown := (audited | declared) - unit_ids:
        issues.append(f"Fact check references unknown script units: {', '.join(sorted(unknown))}.")
    if unaccounted := unit_ids - audited - declared:
        issues.append(
            f"Fact check gives no disposition for script units: {', '.join(sorted(unaccounted))}."
        )
    known_claims = {claim.claim_id for claim in research.all_claims}
    # Auditors sometimes pack several IDs into one field ("C17, C18"); read each one.
    cited = {
        claim_id
        for finding in report.claim_findings
        for claim_id in re.split(r"[\s,;/]+", finding.claim_id or "")
        if claim_id
    }
    if unknown_claims := cited - known_claims:
        issues.append(
            f"Fact check references unknown research claims: {', '.join(sorted(unknown_claims))}."
        )
    known_sources = {source.source_id for source in research.source_references}
    sources = {source for finding in report.claim_findings for source in finding.source_ids}
    if unknown_sources := sources - known_sources:
        issues.append(
            f"Fact check references unknown sources: {', '.join(sorted(unknown_sources))}."
        )
    return issues


def visual_issues(
    visuals: VisualPackage,
    script: ScriptPackage,
    camera_moves: Collection[str],
) -> list[str]:
    """Scenes must partition the narration in order: each unit belongs to exactly one scene."""
    issues: list[str] = []
    unit_order = [unit.unit_id for unit in script.script_units]
    scene_order = [unit_id for scene in visuals.scenes for unit_id in scene.script_unit_ids]
    if unknown := set(scene_order) - set(unit_order):
        issues.append(f"Scenes reference unknown script units: {', '.join(sorted(unknown))}.")
    if uncovered := set(unit_order) - set(scene_order):
        issues.append(f"No scene covers script units: {', '.join(sorted(uncovered))}.")
    if not unknown and not uncovered and scene_order != unit_order:
        issues.append(
            "Scenes must cover the script units once each, in narration order: "
            + ", ".join(unit_order)
            + "."
        )
    first, hook = visuals.scenes[0], script.script_units[0].unit_id
    if first.script_unit_ids[:1] != [hook]:
        issues.append(f"{first.scene_id} must open on the hook: start with {hook}.")
    if not first.reference_ids and first.anchor.figure is None:
        issues.append(
            f"{first.scene_id} is the first image anyone sees: draw it from a real reference "
            "or public figure in the story."
        )
    requested = {reference.ref_id for reference in visuals.references}
    if unknown_refs := sorted(
        {ref for scene in visuals.scenes for ref in scene.reference_ids} - requested
    ):
        issues.append(f"Scenes cite unknown references: {', '.join(unknown_refs)}.")
    if bad_moves := sorted({scene.camera for scene in visuals.scenes} - set(camera_moves)):
        issues.append(
            f"Unknown camera moves: {', '.join(bad_moves)}. "
            f"Use one of: {', '.join(sorted(camera_moves))}."
        )
    return issues


def plan_tasks(
    brief: EditorialBrief,
    research: ResearchPack,
    revision: int,
) -> list[JudgementTask]:
    claims = {claim.claim_id: claim.claim for claim in research.all_claims}
    hook = claims.get(brief.hook_claim_id or "", brief.central_question)
    weighed: list[JudgementTask] = [
        {
            "stage": "plan",
            "revision": revision,
            "target": "claim",
            "target_id": claim_id,
            "state": {"hook": hook, "claim": text},
            "expected": None,
        }
        for claim_id, text in claims.items()
    ]
    return weighed + [
        {
            "stage": "plan",
            "revision": revision,
            "target": "research",
            "target_id": "research",
            "state": {"claims": [claim.claim for claim in research.all_claims]},
            "expected": None,
        },
        {
            "stage": "plan",
            "revision": revision,
            "target": "plan",
            "target_id": "plan",
            "state": {
                "central_question": brief.central_question,
                "promise": brief.promise,
                "arc": [phase.model_dump(mode="json") for phase in brief.arc],
            },
            "expected": None,
        },
    ]


def script_tasks(
    script: ScriptPackage,
    brief: EditorialBrief,
    research: ResearchPack,
    revision: int,
    intended_voice: str = "",
) -> list[JudgementTask]:
    claims = {claim.claim_id: claim for claim in research.all_claims}
    phases = {phase.phase_id: phase for phase in brief.arc}
    units = script.script_units

    def task(
        target: Target,
        target_id: str,
        state: dict[str, Any],
        expected: str | None = None,
    ) -> JudgementTask:
        return JudgementTask(
            stage="script",
            revision=revision,
            target=target,
            target_id=target_id,
            state=state,
            expected=expected,
        )

    tasks = [
        task(
            "opening",
            units[0].unit_id,
            {
                "audience": brief.intended_audience,
                "central_question": brief.central_question,
                "opening": units[0].text,
                "orientation": units[1].text if len(units) > 1 else "",
            },
        )
    ]
    for index, unit in enumerate(units):
        phase = phases[unit.arc_phase_id]
        tasks.append(
            task(
                "unit",
                unit.unit_id,
                {
                    "unit": {"unit_id": unit.unit_id, "text": unit.text},
                    "earlier_units": [earlier.text for earlier in units[:index]],
                    "audience": brief.intended_audience,
                    "narrative_job": phase.narrative_job,
                    "intended_feeling": phase.audience_feeling,
                    # What this line's facts show, from the story ledger: the meaning a
                    # listener should hear beside each fact.
                    "meanings": [
                        plan.meaning
                        for claim_id in unit.claim_ids
                        if (plan := brief.claim_plan(claim_id)) is not None
                        and plan.meaning
                        and (plan.requires_explanation or plan.story_role == "spine")
                    ],
                    "supporting_claims": [
                        {
                            "claim": claims[claim_id].claim,
                            "qualification": claims[claim_id].qualification,
                        }
                        for claim_id in unit.claim_ids
                    ],
                },
            )
        )
    for previous, unit in zip(units, units[1:], strict=False):
        tasks.append(
            task(
                "transition",
                f"{previous.unit_id}->{unit.unit_id}",
                {
                    "audience": brief.intended_audience,
                    "previous_unit": previous.text,
                    "unit": {"unit_id": unit.unit_id, "text": unit.text},
                    # Why the story moves on here, when this unit opens a new beat.
                    "why_next": (
                        phases[previous.arc_phase_id].leads_to_next
                        if previous.arc_phase_id != unit.arc_phase_id
                        else ""
                    ),
                },
                expected=unit.transition_intent,
            )
        )
    tasks.append(
        task(
            "script",
            "script",
            {
                "central_question": brief.central_question,
                "opening": units[0].text,
                "ending": units[-1].text,
                "narration": " ".join(unit.text for unit in units),
                "intended_voice": intended_voice,
            },
        )
    )
    return tasks


def audience_tasks(
    report: AudienceReport, brief: EditorialBrief, revision: int
) -> list[JudgementTask]:
    """Compare what a first-time listener took from the narration with the story ledger:
    one task per beat (did they come away knowing what it should leave them with?) and
    one for the whole (could they retell the story chain?)."""
    heard = report.model_dump(
        include={
            "about",
            "what_happened",
            "why_it_happened",
            "why_it_matters",
            "key_facts",
            "question",
            "unresolved",
        }
    )

    def task(target: Target, target_id: str, state: dict[str, Any]) -> JudgementTask:
        return JudgementTask(
            stage="audience",
            revision=revision,
            target=target,
            target_id=target_id,
            state={"heard": heard, **state},
            expected=None,
        )

    return [
        *(
            task("beat", beat.phase_id, {"audience_should_know": beat.audience_knows_after})
            for beat in brief.arc
        ),
        task(
            "audience",
            "story",
            {"story_chain": brief.story_chain, "central_question": brief.central_question},
        ),
    ]


Stumble = Literal["confusion", "unrelated", "term", "lost_thread"]


class ListenerFinding(NamedTuple):
    """One thing the cold viewer stumbled on, placed on the line it came from."""

    kind: Stumble
    flag: AudienceFlag
    unit_id: str | None


def listener_findings(report: AudienceReport, units: list[ScriptUnit]) -> list[ListenerFinding]:
    stumbles: list[tuple[Stumble, list[AudienceFlag]]] = [
        ("confusion", report.confusions),
        ("unrelated", report.unrelated_facts),
        ("term", report.unclear_terms),
        ("lost_thread", [report.lost_thread_at] if report.lost_thread_at else []),
    ]
    return [
        ListenerFinding(kind, flag, locate(flag.quote, units))
        for kind, flags in stumbles
        for flag in flags
    ]


def listener_line(finding: ListenerFinding) -> str:
    """What the listener experienced, for the writer: an observation, never wording."""
    where = finding.unit_id or "The narration"
    quote, note = finding.flag.quote, finding.flag.note
    return {
        "confusion": f'{where}: a first-time listener was confused by "{quote}": {note}',
        "unrelated": f'{where}: a first-time listener could not tell why "{quote}" is in '
        f"the story: {note}",
        "term": f'{where}: "{quote}" needed knowledge the listener did not have ({note}). '
        "Keep it, translate it, explain it briefly, or cut it.",
        "lost_thread": f"{where}: the listener stopped following why one idea led to the "
        f'next at "{quote}": {note}',
    }[finding.kind]


def apply_story_decisions(brief: EditorialBrief, decisions: StoryDecisions) -> EditorialBrief:
    """The Story Architect's calls, written into the ledger: a cut claim becomes
    expendable and leaves its beats, a demoted one takes its lesser role, a moved one
    changes beat. Keep, simplify, and merge change only how the writer tells it."""
    claims = {plan.claim_id: plan for plan in brief.claims}
    arc = list(brief.arc)
    for decision in decisions.decisions:
        plan = claims.get(decision.claim_id)
        unknown_beat = decision.action == "move" and decision.target not in {
            beat.phase_id for beat in arc
        }
        if plan is None or unknown_beat:
            continue
        if decision.action == "cut":
            claims[plan.claim_id] = plan.model_copy(update={"story_role": "expendable"})
        elif decision.action == "demote":
            claims[plan.claim_id] = plan.model_copy(
                update={"story_role": decision.new_role or "colour"}
            )
        if decision.action in {"cut", "move"}:
            arc = [
                beat.model_copy(
                    update={"claim_ids": [c for c in beat.claim_ids if c != plan.claim_id]}
                )
                for beat in arc
            ]
        if decision.action == "move":
            arc = [
                beat.model_copy(update={"claim_ids": [*beat.claim_ids, plan.claim_id]})
                if beat.phase_id == decision.target
                else beat
                for beat in arc
            ]
    return brief.model_copy(update={"claims": list(claims.values()), "arc": arc})


def locate(quote: str, units: list[ScriptUnit]) -> str | None:
    """The unit a listener's quote comes from: the unit containing it, or else the unit
    whose words it most resembles."""
    wanted = _plain(quote)
    if not wanted:
        return None
    for unit in units:
        if wanted in _plain(unit.text):
            return unit.unit_id
    best = max(
        units,
        key=lambda unit: difflib.SequenceMatcher(None, wanted, _plain(unit.text)).ratio(),
        default=None,
    )
    if best is None:
        return None
    match = difflib.SequenceMatcher(None, wanted, _plain(best.text)).find_longest_match()
    return best.unit_id if match.size >= min(len(wanted), 20) * 0.6 else None


def _plain(text: str) -> str:
    return re.sub(r"[^a-z0-9 ]", "", re.sub(r"\s+", " ", text.lower())).strip()


def visual_tasks(
    visuals: VisualPackage,
    script: ScriptPackage,
    revision: int,
) -> list[JudgementTask]:
    texts = {unit.unit_id: unit.text for unit in script.script_units}
    scenes = visuals.scenes

    def task(target: Target, target_id: str, state: dict[str, Any]) -> JudgementTask:
        return JudgementTask(
            stage="visuals",
            revision=revision,
            target=target,
            target_id=target_id,
            state=state,
            expected=None,
        )

    tasks = [
        task(
            "scene",
            scene.scene_id,
            {
                "scene": {
                    "scene_id": scene.scene_id,
                    "anchor": _anchor_line(scene),
                    "purpose": scene.purpose,
                    "visual_function": scene.visual_function,
                },
                "narration": " ".join(texts[unit_id] for unit_id in scene.script_unit_ids),
            },
        )
        for scene in scenes
    ]
    tasks.extend(
        task(
            "bridge",
            f"{scene.scene_id}->{following.scene_id}",
            {
                "from_scene": _anchor_line(scene),
                "to_scene": _anchor_line(following),
                "morph_bridge": scene.morph_bridge,
            },
        )
        for scene, following in zip(scenes, scenes[1:], strict=False)
    )
    tasks.append(
        task("visual_sequence", "visuals", {"scenes": [_anchor_line(scene) for scene in scenes]})
    )
    return tasks


def _anchor_line(scene: Scene) -> str:
    anchor = scene.anchor
    return f"{anchor.subject}, in {anchor.setting}; {', '.join(anchor.key_elements)}"


def unjudged(tasks: Sequence[JudgementTask], judged: Sequence[Judgement]) -> list[JudgementTask]:
    """The tasks not already answered for this revision: after a line edit, the targets it
    did not touch carry their judgements forward and are not asked again."""
    done = {(QUESTIONS[j.question_id].target, j.target_id) for j in judged}
    return [task for task in tasks if (task["target"], task["target_id"]) not in done]
